// ============================================================================
// Shadow Ledger Writer - Validate Batch
// ----------------------------------------------------------------------------
// FAO-GOV-001: the Writer appends a whole batch or nothing. It reads every
// incoming item ($input.all()), strips keys that start with an underscore,
// and checks each event against the Writer input contract:
//   - event_type is STARTED, ASSET_RECONCILED or FAILED (every other event,
//     including HITL_*, COMMITTED and CORRECTION, is written only by
//     database functions);
//   - required fields, enum values and UUID shape;
//   - event_timestamp, hitl_approver_id, ledger_id and corrects_ledger_id
//     must be absent (the database sets them);
//   - hitl_status is NOT_REQUIRED, or PENDING only on an ASSET_RECONCILED
//     whose outcome rank is >= 2.
// Every problem is collected as "item <i>: <reason>" (i is 0-based, the
// same numbering fao_ledger_append_batch uses) and any problem throws one
// named error, so nothing is silently dropped. A clean batch becomes one
// item {events_json, expected} for Append Ledger Batch, where the database
// runs its own checks (run state, asset scope, duplicates) all or none.
//
// Null optional fields are left out of the stored event: the trigger's input
// schema fills fields a caller did not send with null.
// ============================================================================

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const AGENT = /^[a-z0-9_]{1,64}$/;
const SYMBOL = /^[A-Z0-9]{1,12}$/;
const EVENT_TYPES = ['STARTED', 'ASSET_RECONCILED', 'FAILED'];
const OUTCOME_RANK = { ALLOW: 0, ALLOW_WITH_OBLIGATIONS: 1, REQUIRE_HUMAN: 2, DENY: 3, BLOCKED: 4 };
const SUB_TIERS = ['STANDARD', 'CRITICAL'];
const STATUSES = ['SUCCESS', 'FAILURE', 'PARTIAL', 'ROLLED_BACK'];
const TIERS = ['GREEN', 'AMBER', 'RED'];
const FORBIDDEN = ['event_timestamp', 'hitl_approver_id', 'ledger_id', 'corrects_ledger_id'];
const ALLOWED = [
  'correlation_id', 'event_type', 'inputs', 'policy_outcome', 'policy_sub_tier',
  'policy_rationale', 'obligations', 'status', 'error_details', 'ai_prompt',
  'ai_output', 'ai_confidence', 'fractional_cost_usd', 'hitl_status',
  'execution_id', 'agent_id', 'risk_tier'
];
const MAX_ITEMS = 200;
const MAX_TEXT = 20000;

const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const present = (o, k) => has(o, k) && o[k] !== null && o[k] !== undefined;

const items = $input.all();
const problems = [];
const events = [];

if (items.length < 1 || items.length > MAX_ITEMS) {
  throw new Error(`FAO-GOV-001 writer: batch must hold 1 to ${MAX_ITEMS} events, got ${items.length}`);
}

let first_correlation = null;
let started_seen = 0;
const assets_seen = new Set();

items.forEach((item, i) => {
  const raw = item && isObj(item.json) ? item.json : {};
  const p = [];

  // Strip internal keys.
  const ev = {};
  for (const k of Object.keys(raw)) {
    if (!k.startsWith('_')) ev[k] = raw[k];
  }

  for (const k of FORBIDDEN) {
    if (has(ev, k)) p.push(`${k} must be absent`);
  }
  for (const k of Object.keys(ev)) {
    if (!ALLOWED.includes(k) && !FORBIDDEN.includes(k)) p.push(`unknown field ${k}`);
  }

  // correlation_id
  if (!present(ev, 'correlation_id')) p.push('missing correlation_id');
  else if (typeof ev.correlation_id !== 'string' || !UUID.test(ev.correlation_id)) p.push('correlation_id is not a UUID');
  else {
    if (first_correlation === null) first_correlation = ev.correlation_id.toLowerCase();
    else if (ev.correlation_id.toLowerCase() !== first_correlation) p.push('correlation_id differs from the batch');
  }

  // event_type
  const et = ev.event_type;
  if (!present(ev, 'event_type')) p.push('missing event_type');
  else if (!EVENT_TYPES.includes(et)) p.push('event_type not allowed');

  // inputs
  if (!present(ev, 'inputs')) p.push('missing inputs');
  else if (!isObj(ev.inputs)) p.push('inputs is not an object');
  else if (has(ev.inputs, 'event_type') && ev.inputs.event_type !== et) p.push('inputs.event_type differs from event_type');

  // policy_outcome
  const outcome = ev.policy_outcome;
  if (!present(ev, 'policy_outcome')) p.push('missing policy_outcome');
  else if (!has(OUTCOME_RANK, outcome) || typeof outcome !== 'string') p.push('policy_outcome invalid');

  // policy_rationale
  if (!present(ev, 'policy_rationale')) p.push('missing policy_rationale');
  else if (typeof ev.policy_rationale !== 'string' || ev.policy_rationale.length < 1 || ev.policy_rationale.length > 4000) {
    p.push('policy_rationale must be 1 to 4000 characters');
  }

  // status
  if (!present(ev, 'status')) p.push('missing status');
  else if (!STATUSES.includes(ev.status)) p.push('status invalid');

  // Optional fields.
  if (present(ev, 'policy_sub_tier') && !SUB_TIERS.includes(ev.policy_sub_tier)) p.push('policy_sub_tier invalid');
  if (present(ev, 'execution_id') && (typeof ev.execution_id !== 'string' || !UUID.test(ev.execution_id))) p.push('execution_id is not a UUID');
  if (present(ev, 'agent_id') && (typeof ev.agent_id !== 'string' || !AGENT.test(ev.agent_id))) p.push('agent_id invalid');
  if (present(ev, 'risk_tier') && !TIERS.includes(ev.risk_tier)) p.push('risk_tier invalid');
  if (present(ev, 'obligations')) {
    const ob = ev.obligations;
    if (!Array.isArray(ob) || ob.length > 50 || ob.some(o => typeof o !== 'string' || o.length > 200)) {
      p.push('obligations must be at most 50 strings of at most 200 characters');
    }
  }
  for (const k of ['error_details', 'ai_prompt', 'ai_output']) {
    if (present(ev, k) && (typeof ev[k] !== 'string' || ev[k].length > MAX_TEXT)) p.push(`${k} must be a string of at most ${MAX_TEXT} characters`);
  }
  if (present(ev, 'ai_confidence')) {
    const c = ev.ai_confidence;
    if (typeof c !== 'number' || !Number.isFinite(c) || c < 0 || c > 1) p.push('ai_confidence must be a number from 0 to 1');
  }
  if (present(ev, 'fractional_cost_usd')) {
    const c = ev.fractional_cost_usd;
    if (typeof c !== 'number' || !Number.isFinite(c)) p.push('fractional_cost_usd must be a finite number');
  }
  if (present(ev, 'hitl_status')) {
    const hs = ev.hitl_status;
    if (hs === 'PENDING') {
      if (!(et === 'ASSET_RECONCILED' && has(OUTCOME_RANK, outcome) && OUTCOME_RANK[outcome] >= 2)) {
        p.push('hitl_status PENDING is allowed only on ASSET_RECONCILED with outcome REQUIRE_HUMAN, DENY or BLOCKED');
      }
    } else if (hs !== 'NOT_REQUIRED') {
      p.push('hitl_status must be NOT_REQUIRED or PENDING');
    }
  }

  // Event-specific rules.
  const inputs = isObj(ev.inputs) ? ev.inputs : {};
  if (et === 'STARTED') {
    started_seen += 1;
    if (started_seen > 1) p.push('second STARTED in the batch');
    if (outcome !== 'ALLOW') p.push('STARTED requires policy_outcome ALLOW');
    if (ev.status !== 'SUCCESS') p.push('STARTED requires status SUCCESS');
    const scope = inputs.asset_scope;
    if (!Array.isArray(scope) || scope.length < 1 || scope.length > 50
        || scope.some(s => typeof s !== 'string' || !SYMBOL.test(s))
        || new Set(scope).size !== scope.length) {
      p.push('inputs.asset_scope must be 1 to 50 unique asset symbols');
    } else if (inputs.asset_count !== scope.length) {
      p.push('inputs.asset_count must equal the asset_scope length');
    }
  } else if (et === 'ASSET_RECONCILED') {
    const asset = inputs.asset;
    if (typeof asset !== 'string' || !SYMBOL.test(asset)) p.push('inputs.asset invalid');
    else if (assets_seen.has(asset)) p.push(`duplicate asset ${asset}`);
    else assets_seen.add(asset);
    if ((outcome === 'ALLOW' || outcome === 'ALLOW_WITH_OBLIGATIONS')
        && !(typeof inputs.ratio === 'number' && Number.isFinite(inputs.ratio))) {
      p.push('ALLOW outcomes require a finite numeric inputs.ratio');
    }
  } else if (et === 'FAILED') {
    if (ev.status !== 'FAILURE') p.push('FAILED requires status FAILURE');
  }

  if (p.length > 0) {
    for (const reason of p) problems.push(`item ${i}: ${reason}`);
    return;
  }

  // Normalized event: required fields plus non-null optional fields.
  const out = {};
  for (const k of ALLOWED) {
    if (present(ev, k)) out[k] = ev[k];
  }
  events.push(out);
});

if (problems.length > 0) {
  throw new Error(`FAO-GOV-001 writer: ${problems.join('; ')}`);
}

return [{ json: { events_json: JSON.stringify(events), expected: events.length } }];

// ============================================================================
// Shadow Ledger Writer - Check Inserted
// ----------------------------------------------------------------------------
// FAO-GOV-001: fao_ledger_append_batch is all or none and raises on any bad
// event, so a refused batch already fails Append Ledger Batch. This node
// checks the success path: the stored count must equal the number of events
// sent, else the Writer fails loudly. Output is the Writer's single item
// {count, inserted[]}.
// ============================================================================

const expected = $('Validate Batch').first().json.expected;
const r = (($input.first() || {}).json || {}).r || {};
const count = r.count;

if (r.ok !== true || count !== expected) {
  throw new Error(`FAO-GOV-001 writer: stored ${count} of ${expected}`);
}

return [{ json: { count: r.count, inserted: Array.isArray(r.inserted) ? r.inserted : [] } }];
